import sys
import time

import rospy
from foxglove_msgs.msg import SceneUpdate

topic, fs150_csv, scout_csv, mecanum_csv, marker_color = sys.argv[1:]
expected = {
    "xgc2/px4/" + name
    for name in (part.strip() for part in fs150_csv.split(","))
    if name
}
expected.update({
    "xgc2/scout/" + name
    for name in (part.strip() for part in scout_csv.split(","))
    if name
})
expected.update({
    "xgc2/mecanum/" + name
    for name in (part.strip() for part in mecanum_csv.split(","))
    if name
})
if not expected:
    raise SystemExit("Lichtblick scene readiness requires at least one immutable robot entity")
expected_color = tuple(int(marker_color[index:index + 2], 16) / 255.0 for index in (1, 3, 5))

def label_matches(entity):
    return any(
        abs(text.font_size - 0.24) < 1.0e-9
        and abs(text.color.r - expected_color[0]) < 1.0e-9
        and abs(text.color.g - expected_color[1]) < 1.0e-9
        and abs(text.color.b - expected_color[2]) < 1.0e-9
        and abs(text.color.a - 1.0) < 1.0e-9
        for text in entity.texts
    )

rospy.init_node("xgc2_scene_readiness_probe", anonymous=True, disable_signals=True)
deadline = time.monotonic() + 4.0
seen = set()
while time.monotonic() < deadline:
    remaining = deadline - time.monotonic()
    try:
        message = rospy.wait_for_message(topic, SceneUpdate, timeout=max(0.05, remaining))
    except rospy.ROSException:
        break
    seen.update(entity.id for entity in message.entities if entity.id in expected and label_matches(entity))
    missing = expected - seen
    if not missing:
        raise SystemExit(0)
raise SystemExit("Lichtblick scene is missing styled immutable robot entities: " + ",".join(sorted(expected - seen)))
